#Requires -Version 5.1
# Knoux Repair v2.0.2 | 08-Performance | PF12 - Interactive Optimization Preview
# Risk: READ_ONLY
[CmdletBinding()]
param([switch]$AnalyzeOnly, [switch]$WhatIf, [switch]$EmitJson)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$utf8NoBom=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=$utf8NoBom; $OutputEncoding=$utf8NoBom
Import-Module (Join-Path $PSScriptRoot '..\Core\KnouxRepair.Core.psm1') -Force
function Get-Number([object]$Value){if($null -eq $Value){return 0};try{return [double]$Value}catch{return 0}}
$Session=Start-KnouxSession -ToolId 'PF12' -ToolName 'Interactive Performance Optimization Preview' -Category '08-Performance' -RiskLevel 'READ_ONLY'
try {
  $os=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
  $computer=Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
  $cpu=Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue|Select-Object -First 1
  $cpuPerf=Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction SilentlyContinue|Select-Object -First 1
  $memPerf=Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction SilentlyContinue|Select-Object -First 1
  $diskPerf=@{}; Get-CimInstance Win32_PerfFormattedData_PerfDisk_LogicalDisk -ErrorAction SilentlyContinue|Where-Object{$_.Name -and $_.Name -ne '_Total'}|ForEach-Object{$diskPerf[$_.Name]=$_}
  $totalRam=[math]::Round($computer.TotalPhysicalMemory/1GB,1);$freeRam=[math]::Round($os.FreePhysicalMemory/1MB,1);$usedRam=[math]::Round([math]::Max(0,$totalRam-$freeRam),1);$memLoad=if($totalRam){[math]::Round($usedRam/$totalRam*100,1)}else{0};$cpuLoad=if($cpuPerf){[math]::Round((Get-Number $cpuPerf.PercentProcessorTime),1)}elseif($cpu){[math]::Round((Get-Number $cpu.LoadPercentage),1)}else{0}
  $drives=@(Get-CimInstance Win32_LogicalDisk -Filter "DriveType=3" -ErrorAction SilentlyContinue|ForEach-Object{$counter=$diskPerf[$_.DeviceID];[pscustomobject]@{Name=[string]$_.DeviceID;TotalGB=[math]::Round($_.Size/1GB,1);FreeGB=[math]::Round($_.FreeSpace/1GB,1);UsedPercent=if($_.Size){[math]::Round((1-$_.FreeSpace/$_.Size)*100,1)}else{0};ActiveTimePercent=if($counter){[math]::Round((Get-Number $counter.PercentDiskTime),1)}else{$null}}})
  $top=@(Get-Process -ErrorAction SilentlyContinue|Sort-Object WorkingSet64 -Descending|Select-Object -First 10|ForEach-Object{[pscustomobject]@{Name=$_.ProcessName;Id=$_.Id;MemoryMB=[math]::Round($_.WorkingSet64/1MB,1);CpuSeconds=try{[math]::Round($_.CPU,1)}catch{$null}}})
  $powerText=@(& powercfg.exe /getactivescheme 2>&1|Select-Object -First 1|ForEach-Object{[string]$_});$visualFx=$null;try{$visualFx=(Get-ItemPropertyValue -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name VisualFXSetting -ErrorAction Stop)}catch{}
  $signals=@();if($cpuLoad -ge 85){$signals+=[pscustomobject]@{Code='HIGH_CPU';Level='REVIEW';Message='CPU load is high in this snapshot; inspect top processes before changing services or power settings.';SuggestedTool='SP11'}};if($memLoad -ge 80){$signals+=[pscustomobject]@{Code='MEMORY_PRESSURE';Level='REVIEW';Message='Memory load is high in this snapshot; inspect process working sets before changing paging or services.';SuggestedTool='PF04'}};foreach($d in $drives){if($d.UsedPercent -ge 90){$signals+=[pscustomobject]@{Code='LOW_DISK_SPACE';Level='REVIEW';Message=($d.Name+' is above 90% used; review the cleanup preview before deleting or quarantining anything.');SuggestedTool='SC11'};};if($d.ActiveTimePercent -ge 85){$signals+=[pscustomobject]@{Code='DISK_ACTIVITY';Level='REVIEW';Message=($d.Name+' shows high disk activity in this snapshot; inspect the workload before changing settings.');SuggestedTool='PF05'}}}
  $preview=[pscustomobject]@{CapturedAt=(Get-Date).ToString('o');Cpu=[pscustomobject]@{LoadPercent=$cpuLoad;Name=if($cpu){[string]$cpu.Name}else{'Unknown'};LogicalProcessors=if($cpu){[int]$cpu.NumberOfLogicalProcessors}else{0}};Memory=[pscustomobject]@{TotalGB=$totalRam;UsedGB=$usedRam;FreeGB=$freeRam;LoadPercent=$memLoad;PagesPerSecond=if($memPerf){[int]$memPerf.PagesPersec}else{$null}};Disks=$drives;TopProcesses=$top;ProcessCount=@(Get-Process -ErrorAction SilentlyContinue).Count;PowerPlanEvidence=$powerText;VisualEffectsSetting=$visualFx;Signals=$signals;Safety=[pscustomobject]@{ChangesMade=$false;Sources=@('Win32_OperatingSystem','Win32_ComputerSystem','Win32_PerfFormattedData_PerfOS_Processor','Win32_PerfFormattedData_PerfOS_Memory','Win32_PerfFormattedData_PerfDisk_LogicalDisk','Win32_LogicalDisk','Get-Process','powercfg /getactivescheme','HKCU VisualEffects read');Notice='Read-only optimization evidence. Signals are review prompts, not automatic diagnoses or permission to change services, power, visual effects, processes, or disk settings.'}}
  $preview|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $Session.RawDir 'interactive-optimization-preview.json') -Encoding UTF8;$Session.ItemsFound=$drives.Count+$top.Count;$Session.VerificationPerformed=$true;$Session.VerificationResult='Performance, process, power-plan and visual-effects evidence read only; no changes made.'
  if($EmitJson){Write-Output '---KNOUX_OPTIMIZATION_JSON_START---';$preview|ConvertTo-Json -Depth 8 -Compress;Write-Output '---KNOUX_OPTIMIZATION_JSON_END---'}else{Write-Host ('[OK] Read performance optimization evidence; {0} review signal(s); no changes made.' -f $signals.Count) -ForegroundColor Green}
}catch{$Session.Status='Failed';$Session.ErrorMessage=$_.Exception.Message;Write-Host ('[ERROR] '+$Session.ErrorMessage) -ForegroundColor Red;Write-KnouxLog -Session $Session -Message $Session.ErrorMessage -Level ERROR}
$result=Stop-KnouxSession -Session $Session;Write-KnouxResult -Session $Session;return $result
